mapper.select:
SELECT p.id AS productId, p.name AS productName, p.standard AS standard, u.name AS unitName, combined.batchNo AS batchNo, combined.productionDate AS productionDate, combined.expiryDate AS expiryDate, IFNULL(opening.openingStock, 0) AS openingStock, IFNULL(period.inboundStock, 0) AS inboundStock, IFNULL(period.outboundStock, 0) AS outboundStock, (IFNULL(opening.openingStock, 0) + IFNULL(period.inboundStock, 0) - IFNULL(period.outboundStock, 0)) AS closingStock, p.is_restricted AS isRestricted, p.registration_expiry_date AS registrationExpiryDate, p.agri_type AS agriType FROM erp_product p INNER JOIN ( SELECT DISTINCT product_id, batch_no AS batchNo, production_date AS productionDate, expiry_date AS expiryDate FROM erp_stock_record WHERE deleted = 0
AND warehouse_id = #{req.warehouseId}
AND batch_no LIKE CONCAT('%', #{req.batchNo}, '%')
) combined ON combined.product_id = p.id LEFT JOIN erp_product_unit u ON u.id = p.unit_id AND u.deleted = 0 LEFT JOIN ( SELECT r1.product_id, r1.batch_no, r1.total_count AS openingStock FROM erp_stock_record r1 INNER JOIN ( SELECT product_id, batch_no, MAX(id) AS max_id FROM erp_stock_record WHERE deleted = 0
AND create_time < #{req.beginTime}
GROUP BY product_id, batch_no ) r2 ON r1.id = r2.max_id AND r1.deleted = 0 ) opening ON opening.product_id = combined.product_id AND IFNULL(opening.batch_no, '') = IFNULL(combined.batchNo, '') LEFT JOIN ( SELECT product_id, batch_no, SUM(CASE WHEN count > 0 THEN count ELSE 0 END) AS inboundStock, SUM(CASE WHEN count < 0 THEN ABS(count) ELSE 0 END) AS outboundStock FROM erp_stock_record WHERE deleted = 0
AND create_time >= #{req.beginTime}
AND create_time <= #{req.endTime}
AND warehouse_id = #{req.warehouseId}
GROUP BY product_id, batch_no ) period ON period.product_id = combined.product_id AND IFNULL(period.batch_no, '') = IFNULL(combined.batchNo, '') WHERE p.deleted = 0
AND p.id = #{req.productId}
AND p.agri_type = #{req.agriType}
AND p.name LIKE CONCAT('%', #{req.keyword}, '%')
AND (opening.openingStock > 0 OR period.inboundStock > 0 OR period.outboundStock > 0) ORDER BY p.id, combined.batchNo

SELECT o.no AS orderNo, o.order_time AS orderTime, p.name AS productName, p.registration_no AS registrationNo, p.standard AS standard, p.agri_type AS agriType, p.is_restricted AS isRestricted, i.count AS count, i.product_price AS productPrice, i.total_price AS totalPrice, u.name AS unitName, i.batch_no AS batchNo, i.production_date AS productionDate, i.expiry_date AS expiryDate, c.name AS customerName, o.buyer_id_card AS buyerIdCard, o.usage_intent AS usageIntent, o.dosage_advice AS dosageAdvice FROM erp_sale_order o INNER JOIN erp_sale_order_items i ON o.id = i.order_id AND i.deleted = 0 INNER JOIN erp_product p ON i.product_id = p.id AND p.deleted = 0 LEFT JOIN erp_customer c ON o.customer_id = c.id AND c.deleted = 0 LEFT JOIN erp_product_unit u ON i.product_unit_id = u.id AND u.deleted = 0 WHERE o.deleted = 0 AND p.is_restricted = 1
AND o.order_time >= #{req.beginTime}
AND o.order_time <= #{req.endTime}
AND p.id = #{req.productId}
AND p.name LIKE CONCAT('%', #{req.keyword}, '%')
ORDER BY o.order_time DESC

SELECT o.no AS orderNo, o.order_time AS orderTime, p.name AS productName, p.registration_no AS registrationNo, p.standard AS standard, p.agri_type AS agriType, p.is_restricted AS isRestricted, i.count AS count, i.product_price AS productPrice, i.total_price AS totalPrice, u.name AS unitName, i.batch_no AS batchNo, i.production_date AS productionDate, i.expiry_date AS expiryDate, c.name AS customerName, o.buyer_id_card AS buyerIdCard, o.usage_intent AS usageIntent, o.dosage_advice AS dosageAdvice FROM erp_sale_order o INNER JOIN erp_sale_order_items i ON o.id = i.order_id AND i.deleted = 0 INNER JOIN erp_product p ON i.product_id = p.id AND p.deleted = 0 LEFT JOIN erp_customer c ON o.customer_id = c.id AND c.deleted = 0 LEFT JOIN erp_product_unit u ON i.product_unit_id = u.id AND u.deleted = 0 WHERE o.deleted = 0
AND o.order_time >= #{req.beginTime}
AND o.order_time <= #{req.endTime}
AND p.id = #{req.productId}
AND p.agri_type = #{req.agriType}
AND o.customer_id = #{req.customerId}
AND i.batch_no LIKE CONCAT('%', #{req.batchNo}, '%')
AND p.name LIKE CONCAT('%', #{req.keyword}, '%')
ORDER BY o.order_time DESC

SELECT SUM(total_price)
FROM erp_sale_order
WHERE deleted = 0
  AND status = 20

      AND order_time >= #{beginTime}


      AND order_time <= #{endTime}

SELECT SUM(total_price) FROM erp_finance_receipt
WHERE deleted = 0 AND status = 20
AND receipt_time BETWEEN #{beginTime} AND #{endTime}

SELECT SUM(total_price) FROM erp_finance_payment
WHERE deleted = 0 AND status = 20
AND payment_time BETWEEN #{beginTime} AND #{endTime}

SELECT o.no AS orderNo, o.order_time AS orderTime, s.name AS supplierName, p.name AS productName, p.registration_no AS registrationNo, p.standard AS standard, p.agri_type AS agriType, p.is_restricted AS isRestricted, i.count AS count, u.name AS unitName, i.batch_no AS batchNo, i.production_date AS productionDate, i.expiry_date AS expiryDate, i.product_price AS productPrice, i.total_price AS totalPrice FROM erp_purchase_order o INNER JOIN erp_purchase_order_items i ON o.id = i.order_id AND i.deleted = 0 INNER JOIN erp_product p ON i.product_id = p.id AND p.deleted = 0 LEFT JOIN erp_supplier s ON o.supplier_id = s.id AND s.deleted = 0 LEFT JOIN erp_product_unit u ON i.product_unit_id = u.id AND u.deleted = 0 WHERE o.deleted = 0
AND o.order_time >= #{req.beginTime}
AND o.order_time <= #{req.endTime}
AND p.id = #{req.productId}
AND p.agri_type = #{req.agriType}
AND i.batch_no LIKE CONCAT('%', #{req.batchNo}, '%')
AND p.name LIKE CONCAT('%', #{req.keyword}, '%')
ORDER BY o.order_time DESC
